//! Canonical label lists for the remaining ordinary labelable interfaces.
use super::*;
#[test]
fn remaining_builtin_labels_author_descriptors_saved_native_getters_and_live_iteration(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var tags=['meter','output','progress','select'],names=['HTMLMeterElement','HTMLOutputElement','HTMLProgressElement','HTMLSelectElement'];for(var at=0;at<4;at++){var tag=tags[at],source=document.getElementById(tag),label=document.getElementById(tag+'label'),prototype=window[names[at]].prototype,d=Object.getOwnPropertyDescriptor(prototype,'labels'),labels=source.labels,calls=0;Object.defineProperty(label,'control',{get:function(){calls++;return null;},configurable:true});if(labels.length!==1||labels[0]!==label||calls)throw 'native association ignores author getter';Object.defineProperty(source,'labels',{value:'own',writable:true,configurable:true});source.labels='updated';if(source.labels!=='updated'||d.get.call(source)!==labels)throw 'own shadow';delete source.labels;Object.defineProperty(prototype,'labels',{get:function(){return 'prototype';},configurable:true});if(source.labels!=='prototype'||d.get.call(source)!==labels)throw 'prototype shadow';delete prototype.labels;if(source.labels!==undefined||d.get.call(source)!==labels)throw 'deleted descriptor';Object.defineProperty(prototype,'labels',d);var extra=document.createElement('label');extra.htmlFor=tag;document.body.appendChild(extra);var iterator=labels.values();if(iterator.next().value!==label)throw 'actual iterator';extra.remove();if(!iterator.next().done||labels.length!==1||source.labels!==labels)throw 'live iterator membership';}"#);}
#[test]
fn remaining_builtin_labels_independent_clone_adoption_import_boundaries_and_no_main_slots(){
 let(mut d,mut f,mut p)=fixture();
 run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),target=document.implementation.createHTMLDocument('target'),tags=['meter','output','progress','select'],roots=[],sources=[],sourceLabels=[],held=[],cloned=[];for(var tag of tags){var root=owner.createElement('div'),label=owner.createElement('label'),source=owner.createElement(tag);source.id=tag+'\ud800';label.htmlFor=source.id;root.appendChild(label);root.appendChild(source);var labels=source.labels,clone=root.cloneNode(true),copies=clone.lastChild.labels;if(labels.length!==1||copies===labels||copies.length!==1||copies[0]!==clone.firstChild)throw 'independent actual clone';target.adoptNode(root);target.body.appendChild(root);if(source.ownerDocument!==target||source.labels!==labels||labels[0]!==label)throw 'actual adopted source';roots.push(root);sources.push(source);sourceLabels.push(label);held.push(labels);cloned.push(copies);}"#);
 p.begin_job();run(&mut d,&mut f,&mut p,r#"for(var at of [0,2]){var imported=document.importNode(roots[at],true),field=imported.lastChild,list=field.labels;if(field===sources[at]||field.ownerDocument!==document||field.id!==sources[at].id||list===held[at]||list.length!==1||list[0]!==imported.firstChild||field.getAttributeNode('id')===sources[at].getAttributeNode('id'))throw 'exact independent imported gauge';document.getElementById('mount').appendChild(imported);if(field.labels!==list||list.length!==1||list[0]!==imported.firstChild||sources[at].ownerDocument!==target||sources[at].labels!==held[at])throw 'connected imported gauge labels';}"#);
 for at in [1]{let before=format!("{:?}",d.nodes);let state=(p.state.node_lists.len(),p.state.retained,p.state.dom_commits);p.begin_job();let error=p.runtime.execute(&format!("document.importNode(roots[{at}],true);"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Import supports ordinary HTML containers"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.node_lists.len(),p.state.retained,p.state.dom_commits),state);}
 p.begin_job();run(&mut d,&mut f,&mut p,r#"for(var at=0;at<4;at++){if(sources[at].ownerDocument!==target||sources[at].labels!==held[at]||held[at].length!==1||held[at][0]!==sourceLabels[at]||sourceLabels[at].htmlFor!==sources[at].id)throw 'actual source retained after transfer refusal';var copy=document.importNode(sourceLabels[at],true);copy.htmlFor=tags[at];document.getElementById('mount').appendChild(copy);var main=document.getElementById(tags[at]),list=main.labels;if(list.length!==2||list[1]!==copy||copy.control!==main||copy===sourceLabels[at])throw 'independent imported label association';}var imported=document.importNode(roots[3],true),field=imported.lastChild,list=field.labels;document.getElementById('mount').appendChild(imported);if(list===held[3]||field.labels!==list||list.length!==1||list[0]!==imported.firstChild)throw 'supported native select import';for(var at=0;at<4;at++){sourceLabels[at].htmlFor='absent';if(held[at].length||cloned[at].length!==1)throw 'independent cloned association';}"#);
 let slots=d.nodes.len();p.state.node_limit=slots;p.begin_job();run(&mut d,&mut f,&mut p,r#"for(var tag of tags){var label=owner.createElement('label'),source=owner.createElement(tag);label.appendChild(source);var list=source.labels;if(source.labels!==list||list.length!==1||list[0]!==label)throw 'inert labels without main slots';}"#);assert_eq!(d.nodes.len(),slots);
}
#[test]
fn remaining_builtin_labels_saved_child_getters_preserve_origin_and_fresh_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var tags=['meter','output','progress','select'],names=['HTMLMeterElement','HTMLOutputElement','HTMLProgressElement','HTMLSelectElement'],sources=[],lists=[],getters=[],frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);for(var at=0;at<4;at++){sources.push(document.getElementById(tags[at]));lists.push(sources[at].labels);getters.push(Object.getOwnPropertyDescriptor(frame.contentWindow[names[at]].prototype,'labels').get);if(getters[at].call(sources[at])!==lists[at])throw 'same origin captured identity';}"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://other-remaining-labels.test/",&crate::navigation::Location::home()).unwrap());for at in 0..4{p.begin_job();let error=p.runtime.execute(&format!("getters[{at}].call(sources[{at}]);"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://remaining-labels.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"for(var at=0;at<4;at++)if(getters[at].call(sources[at])!==lists[at]||lists[at].length!==1)throw 'fresh captured getter identity recovery';");}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><label id=meterlabel for=meter>Meter</label><meter id=meter></meter><label id=outputlabel for=output>Output</label><output id=output></output><label id=progresslabel for=progress>Progress</label><progress id=progress></progress><label id=selectlabel for=select>Select</label><select id=select><option value=first>First</option><option value=second>Second</option></select><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://remaining-labels.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn remaining_builtin_labels_canonical_interfaces_brands_and_nodelist_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var tags=['meter','output','progress','select'],names=['HTMLMeterElement','HTMLOutputElement','HTMLProgressElement','HTMLSelectElement'];for(var at=0;at<tags.length;at++){var tag=tags[at],source=document.getElementById(tag),Interface=window[names[at]];if(typeof Interface!=='function'||Object.getPrototypeOf(source)!==Interface.prototype||Object.getPrototypeOf(Interface.prototype)!==HTMLElement.prototype||!(source instanceof Interface)||Object.prototype.toString.call(source)!=='[object '+names[at]+']')throw 'actual canonical HTML interface';var caught=false;try{new Interface();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal interface constructor';var descriptor=Object.getOwnPropertyDescriptor(Interface.prototype,'labels');if(!descriptor||typeof descriptor.get!=='function'||descriptor.set!==undefined||!descriptor.enumerable||!descriptor.configurable||descriptor.get.name!=='get labels'||descriptor.get.length!==0||Object.hasOwn(source,'labels'))throw 'canonical readonly labels descriptor';var labels=source.labels;if(labels!==source.labels||labels!==descriptor.get.call(source)||Object.getPrototypeOf(labels)!==NodeList.prototype||labels.length!==1||labels[0]!==document.getElementById(tag+'label')||labels.item(1)!==null||Object.keys(labels).join(',')!=='0'||Array.from(labels)[0]!==labels[0])throw 'actual stable native NodeList';for(var bad of [{},Object.create(Interface.prototype),document.createElement('input'),document.getElementById(tags[(at+1)%4]),document.createElementNS('urn:foreign',tag)]){caught=false;try{descriptor.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'distinct actual interface brand';}source.labels='ignored';if(source.labels!==labels)throw 'readonly sloppy';caught=false;try{(function(){'use strict';source.labels=null;})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'readonly strict';var count=0;for(var key in source)if(key==='labels')count++;if(count!==1)throw 'enumerable inherited labels';}if(document.getElementById('select').value!=='first')throw 'existing native select value';"#);}
#[test]
fn remaining_builtin_labels_exact_native_associations_and_current_tree_order(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var tag of ['meter','output','progress','select']){var source=document.getElementById(tag),label=document.getElementById(tag+'label'),labels=source.labels;source.id=tag+'\ud800';label.htmlFor=tag+'\ud800';var alias=document.createElement('label');alias.htmlFor=tag+'�';document.body.appendChild(alias);if(labels.length!==1||labels[0]!==label)throw 'exact labels exclude replacement alias';var blocker=document.createElement('div');blocker.id=source.id;document.body.insertBefore(blocker,label);if(labels.length!==0)throw 'first nonlabelable ID blocks association';blocker.remove();var extra=document.createElement('label');extra.htmlFor=source.id;document.body.appendChild(extra);if(labels.length!==2||labels[0]!==label||labels[1]!==extra)throw 'current native tree order';label.remove();document.body.appendChild(label);if(source.labels!==labels||labels.length!==2||labels[1]!==label)throw 'live reinsertion identity';}"#);}
#[test]
fn remaining_builtin_labels_inert_hidden_content_and_actual_detached_roots(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source');for(var tag of ['meter','output','progress','select']){var root=owner.createElement('div'),label=owner.createElement('label'),source=owner.createElement(tag),outside=owner.createElement('label');source.id=tag;label.htmlFor=tag;outside.htmlFor=tag;root.appendChild(label);root.appendChild(source);owner.body.appendChild(outside);var labels=source.labels;if(labels.length!==1||labels[0]!==label||source.labels!==labels)throw 'native detached label list';source.setAttribute('type','hidden');if(source.labels!==labels||labels.length!==1)throw 'noninput hidden content keeps list';owner.body.appendChild(root);if(labels.length!==2||labels[0]!==outside||labels[1]!==label)throw 'actual connected tree';root.remove();if(labels.length!==1||labels[0]!==label)throw 'actual root disconnection';}"#);}

#[test]
fn remaining_builtin_labels_creation_and_refresh_limits_preserve_records_and_recover(){for (id,method) in [("meter","\0HTMLMeterElement.get.labels"),("output","\0HTMLOutputElement.get.labels"),("progress","\0HTMLProgressElement.get.labels"),("select","\0HTMLSelectElement.get.labels")]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some(id)).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.node_lists.len(),p.state.retained,p.state.dom_commits);let retained=p.state.retained_limit;let arenas=p.state.limits.test_entry_arenas;let quota=p.state.limits.host.node_lists;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>{p.state.limits.test_entry_arenas=true;p.state.limits.host.node_lists=p.state.node_lists.len();},3=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_control_labels_get(node_handle(node),method).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.node_lists.len(),p.state.retained,p.state.dom_commits),state);p.state.retained_limit=retained;p.state.limits.test_entry_arenas=arenas;p.state.limits.host.node_lists=quota;p.state.execution_deadline=None;p.begin_job();let list=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_control_labels_get(node_handle(node),method).unwrap();let after=(p.state.node_lists.len(),p.state.retained,p.state.dom_commits);assert_eq!(after.0,state.0+1);for refresh in 0..4{p.begin_job();match refresh{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_labels_list_nodes(node_handle(node)).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.node_lists.len(),p.state.retained,p.state.dom_commits),after);p.state.retained_limit=retained;p.state.execution_deadline=None;}p.begin_job();let recovered=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_control_labels_get(node_handle(node),method).unwrap();assert_eq!(format!("{list:?}"),format!("{recovered:?}"));assert_eq!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_labels_list_nodes(node_handle(node)).unwrap().len(),1);}}}
